def binary_find(values, target):
    low = 0
    high = len(values) - 1
    probes = 0
    while low <= high:
        mid = (low + high) // 2
        probes += 1
        if values[mid] == target:
            return mid, probes
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return None, probes
